new_func = '''def ty_granger(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    T = len(x)
    d_max = max(_adf_order(x), _adf_order(y))
    k = 1
    p_total = k + d_max
    if p_total >= T - 2:
